import { Injectable } from "@angular/core";
import { AuthService } from "../auth/auth.service";

/** Set in environment or chrome://extensions — optional web → extension token sync */
const EXTENSION_ID = "";

declare global {
  interface Window {
    chrome?: {
      runtime?: {
        sendMessage: (
          extensionId: string,
          message: unknown,
          responseCallback?: (response: unknown) => void,
        ) => void;
        lastError?: { message?: string };
      };
    };
  }
}

@Injectable({ providedIn: "root" })
export class ExtensionSyncService {
  constructor(private authService: AuthService) {}

  /**
   * Sends the web app JWT to the extension (requires externally_connectable + extension ID).
   * Paste your extension ID from chrome://extensions into EXTENSION_ID above, or sign in via popup.
   */
  syncAuthToExtension(): Promise<{ ok: boolean; message: string }> {
    const chromeApi = window.chrome;
    if (!chromeApi?.runtime?.sendMessage) {
      return Promise.resolve({
        ok: false,
        message:
          "Chrome extension API not available. Sign in via the extension popup instead.",
      });
    }

    const extensionId = EXTENSION_ID.trim();
    if (!extensionId) {
      return Promise.resolve({
        ok: false,
        message:
          "Extension ID not configured. Sign in via the extension popup, or set EXTENSION_ID in extension-sync.service.ts.",
      });
    }

    const token = this.authService.getToken();
    if (!token) {
      return Promise.resolve({
        ok: false,
        message: "You are not signed in to the web app.",
      });
    }

    return new Promise((resolve) => {
      chromeApi.runtime!.sendMessage(
        extensionId,
        { type: "SET_AUTH", token, expiresIn: 86400 },
        (response: unknown) => {
          if (chromeApi.runtime?.lastError) {
            resolve({
              ok: false,
              message: chromeApi.runtime.lastError.message ?? "Extension unreachable",
            });
            return;
          }
          const body = response as { ok?: boolean; error?: string } | undefined;
          if (body?.ok) {
            resolve({ ok: true, message: "Extension linked successfully." });
            return;
          }
          resolve({
            ok: false,
            message: body?.error ?? "Extension did not accept the token",
          });
        },
      );
    });
  }
}
